arguments.new_string:
return format_version(verinfo['major'], verinfo['minor'], verinfo['patch'], verinfo['prerelease'], verinfo['build'])

def replace(version, **kwargs):
    """Replace components of a version string.

    :param str version: original version string
    :param kwargs: keys may be 'major', 'minor', 'patch', 'prerelease', 'build'
    :return: new version string
    :rtype: str
    """
    verinfo = parse(version)
    for key, value in kwargs.items():
        if key not in verinfo:
            raise TypeError(f"Unknown replacement key: {key}")
        verinfo[key] = value
    return format_version(verinfo['major'], verinfo['minor'], verinfo['patch'], verinfo['prerelease'], verinfo['build'])
